package org.localscape.nylocas.mage;

import org.localscape.nylocas.mage.MageStrategy.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MageCleanupCooperationProbe {
 private Room room(int tick) { Room r = new Room(); r.wave = 31; r.spawns[30] = 260; r.spawns[31] = 264; r.ready = tick; r.specialEnergy = 900; r.player = MageStrategy.tile(3292,4246); return r; }
 private Crab crab(Room r, int key, int wave, int born, Lane lane, char slot, boolean big, Style style, int x, int y) { Crab c = new Crab(key,key,born,wave,lane,slot,big,style,MageStrategy.tile(x,y)); c.pendingDamage = 0; r.crabs.add(c); return c; }
 private Crab oldBody(Room r) { return crab(r,99,29,250,Lane.SPLIT,(char)0,false,Style.RANGE,3298,4248); }
 private static Crab selected(Decision d) { return d.target != null ? d.target : d.approach; }
 @Test public void nativeRangerNullSouth30SurvivorPreemptsFreshUnnulledMagicAt292() { Room r = room(292); r.player = MageStrategy.tile(3300,4249); Crab rescue = crab(r,185,30,260,Lane.SOUTH,'E',false,Style.MAGIC,3299,4244); rescue.hp=5; rescue.partnerNulled=true; crab(r,203,31,279,Lane.SPLIT,(char)0,false,Style.MAGIC,3301,4251); Decision d = new MageStrategy().decide(r,292); assertSame(rescue,d.target); assertEquals(Weapon.EYE,d.weapon); }
 @Test public void newlyVisiblePartnerNullReplacesAnExistingOrdinaryApproach() { Room r = room(292); r.player = MageStrategy.tile(3300,4249); Crab rescue = crab(r,185,30,260,Lane.SOUTH,'E',false,Style.MAGIC,3299,4244); rescue.hp=5; Crab ordinary = crab(r,203,31,279,Lane.SPLIT,(char)0,false,Style.MAGIC,3301,4251); MageStrategy s = new MageStrategy(); assertSame(ordinary,selected(s.decide(r,291))); rescue.partnerNulled=true; assertSame(rescue,s.decide(r,292).target); }
 @Test public void partnerNullRangedBigReceivesNormalPipeDespiteUnassignedBigFilter() { Room r = room(280); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.RANGE,3290,4245); c.partnerNulled=true; oldBody(r); Decision d = new MageStrategy().decide(r,280); assertSame(c,d.target); assertEquals(Weapon.PIPE,d.weapon); }
 @Test public void partnerNullMeleeBigReceivesNormalScythe() { Room r = room(290); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.MELEE,3290,4245); c.partnerNulled=true; oldBody(r); Decision d = new MageStrategy().decide(r,290); assertSame(c,d.target); assertEquals(Weapon.SCYTHE,d.weapon); }
 @Test public void partnerNullReleasesItsStaleUnknownFlightClaim() { Room r = room(280); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.RANGE,3290,4245); c.partnerNulled=true; c.pendingDamage=-1; c.claimedUntil=300; oldBody(r); assertSame(c,new MageStrategy().decide(r,280).target); }
 @Test public void partnerNullReleasesItsUnserviceableNamedRangePacket() { Room r = room(274); r.player = MageStrategy.tile(3298,4248); Crab c = crab(r,1,31,264,Lane.EAST,'S',false,Style.RANGE,3300,4248); c.partnerNulled=true; oldBody(r); assertSame(c,new MageStrategy().decide(r,274).target); }
 @Test public void finalTargetAllowsUnknownPartnerFlight() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.pendingDamage=-1; c.claimedUntil=300; assertSame(c,new MageStrategy().decide(r,280).target); }
 @Test public void finalTargetAllowsKnownNonlethalPartnerFlight() { Room r = room(280); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.RANGE,3290,4245); c.pendingDamage=3; c.hp=8; c.claimedUntil=300; assertSame(c,new MageStrategy().decide(r,280).target); }
 @Test public void finalUnassignedMeleeBigAlsoGetsCooperation() { Room r = room(290); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.MELEE,3290,4245); c.pendingDamage=-1; c.claimedUntil=300; assertSame(c,new MageStrategy().decide(r,290).target); }
 @Test public void provenLethalDamageStillAvoidsAnUnnecessaryFinalAttack() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.pendingDamage=8; c.claimedUntil=300; assertNull(new MageStrategy().decide(r,280).target); }
 @Test public void ownNullStillForbidsFinalOrRescueDamage() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.nulled=true; c.partnerNulled=true; assertNull(new MageStrategy().decide(r,280).target); }
 @Test public void ignoredOldLivingBodyStillPreventsTheFinalTargetException() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.pendingDamage=-1; c.claimedUntil=300; oldBody(r); assertNull(new MageStrategy().decide(r,280).target); }
 @Test public void zeroHpAndDyingBodiesDoNotPreventFinalTargetCooperation() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.pendingDamage=-1; c.claimedUntil=300; oldBody(r).hp=0; Crab body = crab(r,98,29,250,Lane.SPLIT,(char)0,false,Style.MELEE,3297,4247); body.dying=true; assertSame(c,new MageStrategy().decide(r,280).target); }
 @Test public void actual31OldBirthCutoffRemainsEvenForFinalPartnerNullTarget() { Room r = room(280); Crab c = oldBody(r); c.partnerNulled=true; assertNull(new MageStrategy().decide(r,280).target); }
 @Test public void nativeExpiryLimitRemainsEvenForFreshPartnerNullTarget() { Room r = room(313); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.RANGE,3293,4246); c.partnerNulled=true; assertNull(new MageStrategy().decide(r,313).target); }
 @Test public void rescueNeverLaunchesAcrossUpcomingWrongStyleFlicker() { Room r = room(285); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.RANGE,3290,4245); c.partnerNulled=true; oldBody(r); assertNotEquals(Weapon.PIPE,new MageStrategy().decide(r,285).weapon); }
 @Test public void requiredLateDinhStillPreemptsFreshPartnerNullRescue() { Room r = room(208); r.wave=30; r.spawns[28]=200; r.spawns[30]=204; r.player=MageStrategy.tile(3292,4245); Crab primary=crab(r,26,26,188,Lane.SOUTH,'W',true,Style.MELEE,3293,4244); crab(r,28,28,200,Lane.WEST,'N',false,Style.RANGE,3290,4248); Crab rescue=crab(r,30,30,204,Lane.WEST,'S',true,Style.RANGE,3290,4245); rescue.partnerNulled=true; Decision d = new MageStrategy().decide(r,208); assertSame(primary,d.target); assertEquals("26 Dinh on 28",d.rule); }
 @Test public void ordinaryUnknownPartnerLeaseRemainsConservativeWithAnotherLivingBody() { Room r = room(280); Crab c = crab(r,1,31,264,Lane.SPLIT,(char)0,false,Style.MELEE,3293,4246); c.pendingDamage=-1; c.claimedUntil=300; oldBody(r); assertNull(new MageStrategy().decide(r,280).target); }
 @Test public void zeroHpPartnerNullTransientIsNotRescueWork() { Room r = room(280); Crab c = crab(r,1,30,260,Lane.WEST,'S',true,Style.RANGE,3290,4245); c.hp=0; c.partnerNulled=true; oldBody(r); assertNull(new MageStrategy().decide(r,280).target); }
}
